import base64
from pathlib import Path
ICONS = {
  "icon-192.png": "",
  "icon-512.png": "",
  "icon-maskable-192.png": "",
  "icon-maskable-512.png": "",
  "apple-touch-icon.png": ""
}
out = Path("icons")
out.mkdir(parents=True, exist_ok=True)
for name, data in ICONS.items():
    (out / name).write_bytes(base64.b64decode(data))
